#!/usr/bin/env -S uv run --script
# Synced from bootstrap: repo/tools/android/tasks/code-lint-android.py. Do not edit this file.
# The next sync writes it again, and each change in this file is lost.
# /// script
# requires-python = ">=3.14"
# dependencies = []
# ///
# MISE description="Run Android lint on the Gradle modules of the given files"
# MISE hide=true
# MISE tools={uv="latest", python="3.14"}
# USAGE flag "--all" help="lint every file of the repository, not only the uncommitted files"
# USAGE flag "--debug" help="emit debug logs"
# USAGE flag "--fix" help="run lintFix, which applies the safe fixes"
# USAGE arg "[files]" var=#true help="the files to lint; only the Android sources and build files are used, and only their modules are linted; the default is the uncommitted files"
# FILES include="**/src/**/*.kt **/src/**/*.java **/src/**/*.xml *.gradle.kts *.gradle *.pro libs.versions.toml lint.xml lint-baseline.xml"

import os
import posixpath
import shutil
import subprocess
import sys
import tempfile

sys.dont_write_bytecode = True
sys.path.insert(0, f"{os.environ['MISE_PROJECT_ROOT']}/.config/mise/tasks/_scripts")
import helpers  # noqa: E402

# The files and folders that are for the whole build, not for one module.
BUILD_PREFIXES = ("gradle/", "build-logic/", "buildSrc/")
BUILD_FILES = (
  "settings.gradle.kts",
  "settings.gradle",
  "build.gradle.kts",
  "build.gradle",
  "lint.xml",
  "lint-baseline.xml",
)

# A module without the Android Gradle plugin, for example a Kotlin/JVM
# library, has no lint task, and :<module>:lint would stop the build. The
# init script makes one task that runs the lint task of each listed module
# that has one. It finds the project whose canonical projectDir is the
# canonical folder. A folder with no project, for example buildSrc/ or an
# included build, makes the lint run on every module. Every module means each
# project below the Gradle root, so the pub plugins of a Flutter app, which
# are projects of its android/ build, are not linted.
INIT_SCRIPT = """\
gradle.projectsEvaluated { g ->
  def root = g.rootProject
  def rootDir = root.projectDir.toPath().normalize()
  def name = System.getenv("BOOTSTRAP_LINT_TASK")
  def dirs = (System.getenv("BOOTSTRAP_LINT_MODULES") ?: "").tokenize("\\n")
  def projects = root.allprojects.findAll { it.projectDir.toPath().normalize().startsWith(rootDir) }
  if (dirs) {
    def found = dirs.collect { d ->
      def dir = new File(root.projectDir, d).canonicalFile
      root.allprojects.find { it.projectDir.canonicalFile == dir }
    }
    if (!found.contains(null)) projects = found.unique()
  }
  root.tasks.register("bootstrapLint") { t ->
    projects.findAll { it.tasks.names.contains(name) }.each { t.dependsOn(it.tasks.named(name)) }
  }
}
"""


def flag(name):
  """Whether mise gives the flag name as true."""
  return os.environ.get(f"usage_{name}", "false") == "true"


def exit_code(code):
  """The exit code of the shell for a return code of subprocess."""
  return code if code >= 0 else 128 - code


def module_of(root, file):
  """The folder of the module of a file (relative to the Gradle root, "." for
  the root), or "/" when the file is for the whole build: gradle/,
  settings.gradle(.kts), build-logic/, buildSrc/, or the root
  build.gradle(.kts), lint.xml or lint-baseline.xml. A relative folder path is
  never "/", so no module folder is read as that marker. The module is the
  nearest folder with build.gradle.kts or build.gradle, else the root. The
  init script finds the project of that folder, so a projectDir that
  settings.gradle(.kts) remaps is found too.
  """
  if file.startswith(BUILD_PREFIXES) or file in BUILD_FILES:
    return "/"
  folder = posixpath.dirname(file) or "."
  while folder != ".":
    if os.path.isfile(f"{root}/{folder}/build.gradle.kts") or os.path.isfile(f"{root}/{folder}/build.gradle"):
      return folder
    folder = posixpath.dirname(folder) or "."
  return "."


def main():
  os.chdir(os.environ["MISE_PROJECT_ROOT"])

  # Shipped with the android tool. The Gradle root is the root of the
  # repository, else the android/ folder of a Flutter app. Without a Gradle
  # wrapper, the SDK platforms or an AndroidManifest.xml, the task does not
  # apply and prints nothing.
  if os.access("gradlew", os.X_OK):
    root = "."
  elif os.access("android/gradlew", os.X_OK):
    root = "android"
  else:
    sys.exit(0)
  android_home = os.environ.get("ANDROID_HOME", "")
  if not android_home or not os.path.isdir(f"{android_home}/platforms"):
    sys.exit(0)
  # A Gradle build without an AndroidManifest.xml, for example a Kotlin/JVM
  # library, has no Android module. A failed git stops the task, with the
  # error of git.
  result = subprocess.run(
    [
      "git",
      "-c",
      "core.quotePath=off",
      "ls-files",
      "--cached",
      "--others",
      "--exclude-standard",
      "--",
      f"{root}/AndroidManifest.xml",
      f"{root}/*/AndroidManifest.xml",
    ],
    check=False,
    stdout=subprocess.PIPE,
  )
  if result.returncode != 0:
    sys.exit(exit_code(result.returncode))
  if not result.stdout.strip(b"\n"):
    sys.exit(0)

  task = "lintFix" if flag("fix") else "lint"
  info = ["--info"] if flag("debug") else []

  # code:lint passes its flags and files to each code:lint:* task. The list
  # comes from gate_files (the # FILES header above). An empty list: nothing
  # to do.
  args = [f"--{name}" for name in ("all", "debug", "fix") if flag(name)]
  listing = helpers.gate_files(__file__, *args, *helpers.usage_files())
  tmp_dir = None
  try:
    if os.path.getsize(listing) == 0:
      sys.exit(0)

    # Only the modules of the files of the list are linted. modules_arg holds
    # their folders, one on each line; it stays empty for every module, when a
    # file is for the whole build.
    modules = []
    with open(listing, encoding="utf-8", errors="surrogateescape") as lines:
      for file in lines.read().splitlines():
        if root != ".":
          if not file.startswith(f"{root}/"):
            continue
          file = file[len(root) + 1 :]
        modules.append(module_of(root, file))
    if not modules:
      sys.exit(0)
    modules_arg = ""
    if "/" not in modules:
      modules_arg = "\n".join(sorted({m for m in modules if m}))

    tmp_dir = tempfile.mkdtemp(prefix="bootstrap-lint.", dir=os.environ.get("TMPDIR") or "/tmp")
    init_script = f"{tmp_dir}/lint.gradle"
    with open(init_script, "w", encoding="utf-8") as out:
      out.write(INIT_SCRIPT)

    helpers.print_header("Linting the Android modules ...")
    env = dict(os.environ, BOOTSTRAP_LINT_TASK=task, BOOTSTRAP_LINT_MODULES=modules_arg)
    result = subprocess.run(
      ["./gradlew", *info, "--init-script", init_script, ":bootstrapLint"], check=False, cwd=root, env=env
    )
    sys.exit(exit_code(result.returncode))
  finally:
    if tmp_dir:
      shutil.rmtree(tmp_dir, ignore_errors=True)
    os.remove(listing)


main()
